-- Text measures for the picture code: how wide a string is, how it breaks into lines, which colors it carries.
-- The font data comes from the game itself: tests/support/measured_fonts.lua is generated by tools/measured_fonts.py from
-- what /im facts measured in the beta (the file, size and color of each font object, the height of a line, and the advance
-- of every printable character). A character's width is its advance, so the width of a string is their sum: good to a few
-- percent, which is enough to see whether text fits a box (the game also rounds to whole pixels and may kern a pair).
-- A font marked approximate in that file was measured by a run that only had characters alone, scaled down.
--
--   local Metrics = dofile("tests/support/metrics.lua")
--   Metrics.width("|cffa335eeBlade of the Fixture|r", 12, "GameFontNormal")   -- escapes do not count
--   local lines = Metrics.layout(text, 12, 200, true, false, "GameFontNormal")  -- wrapped at 200 pixels
--   lines[1].runs[1].text, lines[1].runs[1].color, lines[1].width
--
-- A font name is optional: without one the text is measured in GameFontNormal's face scaled to the size. A test of the
-- line breaking itself can set Metrics.estimate = true for a flat model (letters half an em wide, narrow and wide ones,
-- digits, capitals) and put it back after.

-- One copy for the whole run (every module that loads this file shares it, so a test can switch the model for all of them).
local cached = package.loaded["intrepid.metrics"]
if cached then return cached end

local Measured = dofile("tests/support/measured_fonts.lua")

local Metrics = {}
package.loaded["intrepid.metrics"] = Metrics

Metrics.estimate = false
Metrics.DEFAULT_FONT_NAME = "GameFontNormal"

-- The font objects the game has, as /im facts found them: size, color, file, flags, and the height of one line.
Metrics.FONT_OBJECTS = {}
for name, font in pairs(Measured) do
  Metrics.FONT_OBJECTS[name] = {
    size = font.size, color = font.color, path = font.path, flags = font.flags, lineHeight = font.lineHeight, approximate = font.approximate,
  }
end
-- Text written with no font object of its own (the size 12 default of the stand-ins).
Metrics.DEFAULT_FONT = { size = 12, color = { 1, 1, 1 } }

-- The font object whose file is `path` and whose size is nearest to `size` (for text given SetFont(path, size)), or nil.
function Metrics.font_for_path(path, size)
  local best, distance
  for name, font in pairs(Measured) do
    if font.path == path then
      local gap = math.abs(font.size - (size or font.size))
      if not distance or gap < distance or (gap == distance and name < best) then best, distance = name, gap end
    end
  end
  return best
end

local NARROW = "ijlI1.,:;'|!`()[]"
local WIDE = "mwMW@%"

-- The flat model: the width of one character in ems.
local function charEm(char)
  if char == " " then return 0.28 end
  if string.find(char, "%d") then return 0.55 end
  if string.find(NARROW, char, 1, true) then return 0.30 end
  if string.find(WIDE, char, 1, true) then return 0.82 end
  if string.find(char, "%u") then return 0.64 end
  return 0.50
end

local function fontData(fontName)
  return Measured[fontName or Metrics.DEFAULT_FONT_NAME] or Measured[Metrics.DEFAULT_FONT_NAME]
end

-- Width of plain text (no escapes) in pixels at `size`. Bytes of a multi-byte character after the first count nothing.
local function plainWidth(text, size, fontName)
  local total = 0
  if Metrics.estimate then
    for i = 1, #text do
      local byte = string.byte(text, i)
      if byte < 128 then
        total = total + charEm(string.sub(text, i, i))
      elseif byte >= 192 then
        total = total + 0.52
      end
    end
    return total * size
  end
  local font = fontData(fontName)
  local advances = font.advances
  for i = 1, #text do
    local byte = string.byte(text, i)
    if byte >= 32 and byte <= 126 then
      total = total + advances[byte - 31]
    elseif byte >= 192 then
      total = total + 0.52 * font.size
    end
  end
  return total * size / font.size
end

-- The height of one line of text in a font at `size`: the game's own figure for the font, scaled.
function Metrics.line_height(size, fontName)
  if Metrics.estimate then return math.floor(size * 1.2 + 0.5) end
  local font = fontData(fontName)
  return size * font.lineHeight / font.size
end

-- Reads the escapes of the game's text into runs: { text = "...", color = {r, g, b, a} or nil }, { icon = {height,
-- width} } and { newline = true }. Supported: |cAARRGGBB ... |r, |Hlink|h[text]|h (the link data is dropped, the
-- text kept), |Tpath:height:width...|t, |Aatlas:height:width...|a, |n and ||.
function Metrics.parse(text)
  text = string.gsub(text, "\n", "|n") -- a new line in the text breaks the line like |n does
  local runs, color = {}, nil
  local buffer = {}
  local function flush()
    if #buffer > 0 then
      runs[#runs + 1] = { text = table.concat(buffer), color = color }
      buffer = {}
    end
  end
  local pos, length = 1, #text
  while pos <= length do
    local bar = string.find(text, "|", pos, true)
    if not bar then
      buffer[#buffer + 1] = string.sub(text, pos)
      break
    end
    if bar > pos then buffer[#buffer + 1] = string.sub(text, pos, bar - 1) end
    local kind = string.sub(text, bar + 1, bar + 1)
    if kind == "|" then
      buffer[#buffer + 1] = "|"
      pos = bar + 2
    elseif kind == "n" then
      flush()
      runs[#runs + 1] = { newline = true }
      pos = bar + 2
    elseif kind == "c" and string.find(text, "^%x%x%x%x%x%x%x%x", bar + 2) then
      flush()
      local hex = string.sub(text, bar + 2, bar + 9)
      color = {
        tonumber(string.sub(hex, 3, 4), 16) / 255, tonumber(string.sub(hex, 5, 6), 16) / 255,
        tonumber(string.sub(hex, 7, 8), 16) / 255, tonumber(string.sub(hex, 1, 2), 16) / 255,
      }
      pos = bar + 10
    elseif kind == "r" then
      flush()
      color = nil
      pos = bar + 2
    elseif kind == "H" then
      local close = string.find(text, "|h", bar + 2, true)
      pos = close and close + 2 or bar + 2
    elseif kind == "h" then
      pos = bar + 2
    elseif kind == "T" or kind == "A" then
      local closer = kind == "T" and "|t" or "|a"
      local close = string.find(text, closer, bar + 2, true)
      if close then
        flush()
        local spec = string.sub(text, bar + 2, close - 1)
        local height, width = string.match(spec, "^[^:]*:(%d+):?(%d*)")
        height = tonumber(height) or 0
        runs[#runs + 1] = { icon = { height = height, width = tonumber(width) or height } }
        pos = close + 2
      else
        pos = bar + 2
      end
    else
      buffer[#buffer + 1] = "|"
      pos = bar + 1
    end
  end
  flush()
  return runs
end

-- Cuts text runs into chunks that are words, runs of spaces or icons, each keeping its color (the color table is
-- shared by the chunks of one run, which is how they are joined again after the breaks are found).
local function chunks(runs, size, fontName)
  local out = {}
  for _, run in ipairs(runs) do
    if run.newline then
      out[#out + 1] = { newline = true }
    elseif run.icon then
      local width = run.icon.width > 0 and run.icon.width or size
      out[#out + 1] = { icon = run.icon, width = width, color = run.color }
    else
      local pos = 1
      while pos <= #run.text do
        local space = string.match(run.text, "^ +", pos)
        local word = not space and string.match(run.text, "^[^ ]+", pos)
        local piece = space or word
        out[#out + 1] = { text = piece, color = run.color, space = space ~= nil, width = plainWidth(piece, size, fontName) }
        pos = pos + #piece
      end
    end
  end
  return out
end

-- Breaks text into lines. `maxWidth` is the width to wrap at (nil: do not wrap), `wrap` false stops wrapping.
-- `breakLong` is what a multi-line edit box does: a word wider than a whole line is cut at the character that overflows
-- (otherwise it stays on a line of its own, wider than the box). The characters are bytes; such text is ASCII here.
-- Returns a list of { runs = {...}, width = n }; the first line exists even for empty text.
function Metrics.layout(text, size, maxWidth, wrap, breakLong, fontName)
  local lines = {}
  local current = { runs = {}, width = 0 }
  local function finish()
    -- spaces at the end of a line are not part of it
    while #current.runs > 0 and current.runs[#current.runs].space do
      local last = table.remove(current.runs)
      current.width = current.width - last.width
    end
    -- neighbouring pieces of one color are one run (the words and spaces were only for finding the breaks)
    local joined = {}
    for _, run in ipairs(current.runs) do
      local before = joined[#joined]
      if before and before.text and run.text and before.color == run.color then
        before.text = before.text .. run.text
        before.width = before.width + run.width
      else
        joined[#joined + 1] = run
      end
    end
    current.runs = joined
    lines[#lines + 1] = current
    current = { runs = {}, width = 0 }
  end
  for _, chunk in ipairs(chunks(Metrics.parse(text or ""), size, fontName)) do
    if chunk.newline then
      finish()
    elseif breakLong and maxWidth and wrap ~= false and chunk.text and not chunk.space and chunk.width > maxWidth + 0.001 then
      -- a word wider than a line: it starts on a line of its own, then fills whole lines
      local word, pos = chunk.text, 1
      local function charWidth(at) return plainWidth(string.sub(word, at, at), size, fontName) end
      if #current.runs > 0 then finish() end
      while pos <= #word do
        local taken, used = 0, 0
        while pos + taken <= #word do
          local width = charWidth(pos + taken)
          if taken > 0 and current.width + used + width > maxWidth + 0.001 then break end
          taken, used = taken + 1, used + width
        end
        current.runs[#current.runs + 1] = { text = string.sub(word, pos, pos + taken - 1), color = chunk.color, space = false, width = used }
        current.width = current.width + used
        pos = pos + taken
        if pos <= #word then finish() end
      end
    else
      local fits = not (maxWidth and wrap ~= false) or current.width + chunk.width <= maxWidth + 0.001
      if not fits and #current.runs > 0 and not chunk.space then finish() end
      current.runs[#current.runs + 1] = chunk
      current.width = current.width + chunk.width
    end
  end
  finish()
  return lines
end

-- The width of the widest line when nothing wraps (explicit new lines still break).
function Metrics.width(text, size, fontName)
  local widest = 0
  for _, line in ipairs(Metrics.layout(text, size, nil, false, false, fontName)) do
    if line.width > widest then widest = line.width end
  end
  return widest
end

return Metrics
